export function createMemo(fetchValue) {
  const cache = new Map();

  return {
    get(key) {
      if (cache.has(key)) return cache.get(key);

      let resolvePending;
      let rejectPending;

      const pending = new Promise((resolve, reject) => {
        resolvePending = resolve;
        rejectPending = reject;
      });

      cache.set(key, pending);

      pending.then(undefined, () => {
        cache.delete(key);
      });

      try {
        resolvePending(fetchValue(key));
      } catch (error) {
        rejectPending(error);
      }

      return pending;
    },

    has(key) {
      return cache.has(key);
    }
  };
}
